using System.Reflection;using NUnit.Framework;using UnityEditor;using UnityEditor.AddressableAssets;using UnityEngine;using UnityEngine.UI;using Rootborn.UI.Modern;using Rootborn.UI.StudentLife;namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanDailyPlannerArtTests{[Test]public void PlannerIconUsesSavedCrispSpriteAndDedicatedThemeEntry(){const string path="Assets/Art/UI/UrbanMolding/daily_planner.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null,"Reviewed Comfy planner must be imported");Assert.That(s.rect.size,Is.EqualTo(new Vector2(64,64)));Assert.That(s.pivot,Is.EqualTo(new Vector2(32,32)));Assert.That(s.pixelsPerUnit,Is.EqualTo(16));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));Assert.That(AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path)).address,Is.EqualTo("sprites/ui/urban-life/daily-planner"));var theme=AssetDatabase.LoadAssetAtPath<UrbanUiThemeDefinition>("Assets/Data/UI/UrbanMoldingTheme.asset");Assert.That(theme.GetIcon("daily-planner"),Is.SameAs(s));Assert.That(theme.GetIcon("plan").name,Is.EqualTo("urban_icon_plan"),"Existing route fallback atlas remains intact");}[Test]public void ExistingPlanTitleUsesDedicatedDecorativeBindingWithoutChangingItsGeometry(){var go=new GameObject("PlannerArtFixture",typeof(RectTransform));try{var panel=go.AddComponent<DailyPlanPanel>();typeof(DailyPlanPanel).GetMethod("EnsureLayout",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(panel,null);var icon=go.transform.Find("PlanIcon");Assert.That(icon,Is.Not.Null);Assert.That(new SerializedObject(icon.GetComponent<UrbanUiIcon>()).FindProperty("_key").stringValue,Is.EqualTo("daily-planner"));Assert.That(icon.GetComponent<Image>().raycastTarget,Is.False);Assert.That(((RectTransform)icon).sizeDelta,Is.EqualTo(new Vector2(72,72)));Assert.That(((RectTransform)icon).anchoredPosition,Is.EqualTo(new Vector2(48,-92)));}finally{Object.DestroyImmediate(go);}}}}
